import Foundation
import XCTest
@testable import Dictate_Anywhere

/// Exact human references are bundled with the benchmark, not generated by ASR.
struct GoldenSpeechFixture: Decodable {
    enum Metric: String, Decodable { case wer, cer }
    let id: String
    let language: String
    let metric: Metric
    let audio: String
    let reference: String
    let sampleCount: Int
    let source: String
    let sourceId: String
    let tags: [String]
    let audioSHA256: String
    let referenceSHA256: String

    static func all() throws -> [Self] {
        let url = try resource("golden-speech-manifest.json")
        return try JSONDecoder().decode([Self].self, from: Data(contentsOf: url))
    }

    static func resource(_ name: String) throws -> URL {
        let path = name as NSString
        return try XCTUnwrap(Bundle(for: GoldenSpeechFixtureTests.self).url(
            forResource: path.deletingPathExtension, withExtension: path.pathExtension
        ), "Missing bundled golden resource: \(name)")
    }

    var audioURL: URL { get throws { try Self.resource(audio) } }
    var referenceText: String { get throws { try String(contentsOf: Self.resource(reference), encoding: .utf8) } }

    func supports(_ model: ParakeetModelChoice) -> Bool {
        switch model {
        case .multilingual, .multilingualUltra: return ["en", "nl", "de"].contains(language)
        case .nemotronMultilingual: return true
        case .senseVoice: return ["en", "zh", "zh-en"].contains(language)
        case .englishOnly, .compactEnglish, .parakeetEou320, .nemotron560, .nemotron1120, .nemotron2240:
            return language == "en"
        }
    }

    func errorRate(hypothesis: String) throws -> Double {
        Self.errorRate(reference: try referenceText, hypothesis: hypothesis, metric: metric)
    }

    static func errorRate(reference: String, hypothesis: String, metric: Metric) -> Double {
        switch metric {
        case .wer: return benchmarkWordErrorRate(reference: reference, hypothesis: hypothesis)
        case .cer:
            // Preserve numbers and words. Only ignore case, Unicode width,
            // punctuation and whitespace, including the derived bilingual clip.
            return characterErrorRate(
                reference: reference.folding(options: [.caseInsensitive, .widthInsensitive], locale: nil),
                hypothesis: hypothesis.folding(options: [.caseInsensitive, .widthInsensitive], locale: nil)
            )
        }
    }
}
